var bytes = require('..');

describe('proof', function () {
  it('parses multi-digit values with units', function () {
    assert.strictEqual(bytes('10kb'), 10240);
  });

  it('parses large multi-digit values with units', function () {
    assert.strictEqual(bytes.parse('1024mb'), 1073741824);
  });

  it('parses negative multi-digit values with units', function () {
    assert.strictEqual(bytes.parse('-10kb'), -10240);
  });

  it('parses multi-digit decimal values with units', function () {
    assert.strictEqual(bytes.parse('10.5kb'), 10752);
  });
});
"}, "note": "The parse regex lost its '+' quantifier (\d+ became \d), so multi-digit values with a unit (e.g. '10kb', '1024mb', '-10kb', '10.5kb') no longer match and fall back to parseInt with unit 'b', returning the bare integer instead of the converted byte value."}
```

